// LRU Cache Layer for FreeLang Runtime
// Optimizes function results and value caching with time-based expiration

use std::collections::HashMap;
use std::time::{SystemTime, UNIX_EPOCH};
use crate::core::Value;

/// Cache entry with expiration time
#[derive(Clone, Debug)]
struct CacheEntry {
    value: Value,
    created_at: u64,
    accessed_count: u32,
}

/// LRU Cache key - function name + argument hash
#[derive(Clone, Debug, Eq, PartialEq, Hash)]
pub struct CacheKey {
    func_name: String,
    arg_hash: u64,
}

impl CacheKey {
    /// Create new cache key
    pub fn new(func_name: String, arg_hash: u64) -> Self {
        CacheKey { func_name, arg_hash }
    }

    /// Compute hash for arguments
    pub fn hash_args(args: &[Value]) -> u64 {
        let mut hash: u64 = 5381;
        for arg in args {
            hash = hash.wrapping_mul(33).wrapping_add(arg.hash_value());
        }
        hash
    }
}

/// LRU Cache with time-based expiration
pub struct LRUCache {
    cache: HashMap<CacheKey, CacheEntry>,
    access_order: Vec<CacheKey>,
    max_size: usize,
    ttl_ms: u64,
    hits: u64,
    misses: u64,
    evictions: u64,
}

impl LRUCache {
    /// Create new LRU cache
    /// max_size: maximum number of entries (default 1000)
    /// ttl_ms: time-to-live in milliseconds (default 60000)
    pub fn new(max_size: usize, ttl_ms: u64) -> Self {
        LRUCache {
            cache: HashMap::with_capacity(max_size),
            access_order: Vec::with_capacity(max_size),
            max_size,
            ttl_ms,
            hits: 0,
            misses: 0,
            evictions: 0,
        }
    }

    /// Create default cache (1000 entries, 60 second TTL)
    pub fn default_cache() -> Self {
        LRUCache::new(1000, 60000)
    }

    /// Get current timestamp in milliseconds
    fn now_ms() -> u64 {
        SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_millis() as u64
    }

    /// Get value from cache
    pub fn get(&mut self, key: &CacheKey) -> Option<Value> {
        if let Some(entry) = self.cache.get_mut(key) {
            // Check if entry has expired
            let age_ms = Self::now_ms().wrapping_sub(entry.created_at);
            if age_ms > self.ttl_ms {
                self.cache.remove(key);
                self.misses += 1;
                return None;
            }

            // Update access info
            entry.accessed_count = entry.accessed_count.saturating_add(1);

            // Move to end of access order (most recently used)
            self.access_order.retain(|k| k != key);
            self.access_order.push(key.clone());

            self.hits += 1;
            Some(entry.value.clone())
        } else {
            self.misses += 1;
            None
        }
    }

    /// Insert value into cache
    pub fn insert(&mut self, key: CacheKey, value: Value) {
        // Check if at capacity
        if self.cache.len() >= self.max_size && !self.cache.contains_key(&key) {
            self.evict_lru();
        }

        let entry = CacheEntry {
            value,
            created_at: Self::now_ms(),
            accessed_count: 1,
        };

        self.cache.insert(key.clone(), entry);
        self.access_order.push(key);
    }

    /// Evict least recently used entry
    fn evict_lru(&mut self) {
        if let Some(lru_key) = self.access_order.first().cloned() {
            self.cache.remove(&lru_key);
            self.access_order.remove(0);
            self.evictions += 1;
        }
    }

    /// Clear entire cache
    pub fn clear(&mut self) {
        self.cache.clear();
        self.access_order.clear();
    }

    /// Remove expired entries
    pub fn cleanup_expired(&mut self) {
        let now = Self::now_ms();
        let expired_keys: Vec<_> = self
            .cache
            .iter()
            .filter(|(_, entry)| now.wrapping_sub(entry.created_at) > self.ttl_ms)
            .map(|(k, _)| k.clone())
            .collect();

        for key in expired_keys {
            self.cache.remove(&key);
            self.access_order.retain(|k| k != &key);
        }
    }

    /// Get cache statistics
    pub fn stats(&self) -> CacheStats {
        let total_requests = self.hits + self.misses;
        let hit_rate = if total_requests > 0 {
            (self.hits as f64 / total_requests as f64) * 100.0
        } else {
            0.0
        };

        CacheStats {
            hits: self.hits,
            misses: self.misses,
            hit_rate,
            evictions: self.evictions,
            entries: self.cache.len(),
            max_size: self.max_size,
        }
    }

    /// Get cache size
    pub fn size(&self) -> usize {
        self.cache.len()
    }

    /// Check if cache is full
    pub fn is_full(&self) -> bool {
        self.cache.len() >= self.max_size
    }
}

/// Cache statistics
#[derive(Clone, Debug)]
pub struct CacheStats {
    pub hits: u64,
    pub misses: u64,
    pub hit_rate: f64,
    pub evictions: u64,
    pub entries: usize,
    pub max_size: usize,
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_cache_basic_set_get() {
        let mut cache = LRUCache::new(10, 60000);
        let key = CacheKey::new("abs".to_string(), 42);
        let value = Value::Number(5.0);

        cache.insert(key.clone(), value.clone());
        assert_eq!(cache.get(&key).unwrap(), value);
    }

    #[test]
    fn test_cache_miss() {
        let mut cache = LRUCache::new(10, 60000);
        let key = CacheKey::new("abs".to_string(), 42);
        assert!(cache.get(&key).is_none());
