    #[test]
    fn test_cache_lru_access_ordering() {
        let mut cache = LRUCache::new(2, 60000);

        let key1 = CacheKey::new("f1".to_string(), 1);
        let key2 = CacheKey::new("f2".to_string(), 2);
        let key3 = CacheKey::new("f3".to_string(), 3);

        cache.insert(key1.clone(), Value::Number(1.0));
        cache.insert(key2.clone(), Value::Number(2.0));

        // Access key1 to make it more recently used
        cache.get(&key1);

        // Add key3, should evict key2
        cache.insert(key3.clone(), Value::Number(3.0));

        assert!(cache.get(&key1).is_some());
        assert!(cache.get(&key2).is_none()); // Should be evicted
        assert!(cache.get(&key3).is_some());
    }

